function tr(key){var lang=state&&state.lang==='es'?'es':'en';return (T[lang]&&T[lang][key])||T.en[key]||key;}
function esc(value){return String(value==null?'':value).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
function clean(value,max){return String(value==null?'':value).replace(/[\u0000-\u001f\u007f]/g,' ').replace(/\s+/g,' ').trim().slice(0,max||160);}
function pad(n){return n<10?'0'+n:String(n);}
function isoDate(date){return date.getFullYear()+'-'+pad(date.getMonth()+1)+'-'+pad(date.getDate());}
function addDays(days){var d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()+days);return isoDate(d);}
function dateObj(value){var p=String(value||'').split('-');return new Date(Number(p[0]),Number(p[1])-1,Number(p[2]),12,0,0,0);}
function isPast(value){var d=dateObj(value),n=new Date();n.setHours(0,0,0,0);return d<n;}
function daysUntil(value){var n=new Date();n.setHours(0,0,0,0);return Math.ceil((dateObj(value)-n)/86400000);}
function fmtDate(value){try{return dateObj(value).toLocaleDateString(state.lang==='es'?'es-US':'en-US',{month:'short',day:'numeric',year:'numeric'});}catch(e){return value;}}
function hoursText(minutes){var h=Math.floor(minutes/60),m=minutes%60;return h+' '+tr('hours')+(m?' '+m+' '+tr('mins'):'');}
function initials(name){return clean(name,80).split(' ').filter(Boolean).slice(0,2).map(function(x){return x.charAt(0).toUpperCase();}).join('')||'MR';}
function local(obj,key){if(state.lang==='es'&&obj[key+'Es'])return obj[key+'Es'];return obj[key]||'';}
