function approvalKeyFor(w,s){s=s||state;return [SITE_ID,w.employer,w.workOrder,w.role,w.crew,s.siteNoticeVersion,s.plan.version].join('|').toLowerCase();}
function load(){
 try{
  var params=new URLSearchParams(location.search),reset=params.get('reset');
  if(reset==='1'){
   var resetMessage=params.get('lang')==='es'?'¿Restablecer todos los datos locales de demostración?':'Reset all local demonstration data?';
   if(window.confirm(resetMessage))localStorage.removeItem(STORE);
  }
  var raw=localStorage.getItem(STORE);if(raw){var parsed=JSON.parse(raw);if(parsed&&parsed.version===VERSION&&Array.isArray(parsed.workers)&&Array.isArray(parsed.assignments)&&Array.isArray(parsed.records))return parsed;}
 }catch(e){}
 return makeInitial();
}
var state=load();
function save(){try{localStorage.setItem(STORE,JSON.stringify(state));}catch(e){}}
function worker(id){for(var i=0;i<state.workers.length;i++)if(state.workers[i].id===id)return state.workers[i];return null;}
function assignment(id){for(var i=0;i<state.assignments.length;i++)if(state.assignments[i].id===id)return state.assignments[i];return null;}
function annualMinutes(id){return state.records.filter(function(r){return r.workerId===id&&r.annualCredit;}).reduce(function(sum,r){return sum+Number(r.annualCreditedMinutes!=null?r.annualCreditedMinutes:(r.minutes||0));},0);}
function annualPending(id){return state.assignments.filter(function(a){return a.workerId===id&&a.status==='awaiting_review'&&a.annualCreditRequested;}).reduce(function(sum,a){return sum+Number(a.completedMinutes||a.minutes||0);},0);}
function categoryMinutes(id,cat){return state.records.filter(function(r){return r.workerId===id&&r.annualCredit&&r.category===cat;}).reduce(function(sum,r){return sum+Number(r.annualCreditedMinutes!=null?r.annualCreditedMinutes:(r.minutes||0));},0);}
function programAssessment(w){
 var out={blocked:false,restriction:'',reason:'',owner:'employer'};
 if(w.program==='46.8'){
  if(!w.annualCurrentThrough||isPast(w.annualCurrentThrough)){out.blocked=true;out.reason='expired';}
  return out;
 }
 if(w.program==='46.5'){
  if(Number(w.preWorkMinutes||0)<240||!w.preWorkSubjectsComplete){out.blocked=true;out.reason='preworkMissing';return out;}
  if(isPast(w.sixtyDayDue)&&(!w.firstAidComplete||(w.respiratoryRequired&&!w.respiratoryComplete))){out.blocked=true;out.reason='sixtyMissing';return out;}
  if(isPast(w.ninetyDayDue)&&Number(w.total46_5Minutes||0)<1440){out.blocked=true;out.reason='ninetyMissing';return out;}
  if(Number(w.total46_5Minutes||0)<1440){if(!w.observer){out.blocked=true;out.reason='observerMissing';return out;}out.restriction='observerRequired';}
  return out;
 }
 if(w.program==='46.6'){
  if(!w.experienceVerified){out.blocked=true;out.reason='experienceMissing';return out;}
  if(Number(w.preWorkSubjects||0)<7){out.blocked=true;out.reason='subjectsMissing';return out;}
  if(w.respiratoryRequired&&isPast(w.respiratoryDue)&&!w.respiratoryComplete){out.blocked=true;out.reason='sixtyMissing';return out;}
 }
 return out;
}
function readiness(w){
 var p=programAssessment(w),result={code:'clear',reason:'',owner:'mine',restriction:p.restriction};
 if(w.hold)return {code:'hold',reason:'holdActive',owner:'mine',restriction:''};
 if(!w.identity)return {code:'blocked',reason:'identityMissing',owner:'employer',restriction:''};
 if(p.blocked)return {code:'blocked',reason:p.reason,owner:p.owner,restriction:''};
 if(!w.taskCurrent)return {code:'blocked',reason:'taskMissing',owner:'employer',restriction:p.restriction};
 if(!w.orientationCurrent)return {code:'pending',reason:'orientationMissing',owner:'mine',restriction:p.restriction};
 if(Number(w.noticeVersion||0)!==Number(state.siteNoticeVersion))return {code:'pending',reason:'noticeMissing',owner:'mine',restriction:p.restriction};
 if(!w.mineApproval||w.approvalKey!==approvalKeyFor(w))return {code:'pending',reason:'approvalMismatch',owner:'mine',restriction:p.restriction};
 if(p.restriction)return {code:'restricted',reason:p.restriction,owner:'mine',restriction:p.restriction};
 return result;
}
function statusLabel(code){return code==='clear'?tr('clearAssignment'):code==='restricted'?tr('clearRestriction'):code==='hold'?tr('holdActive'):tr('notClear');}
function ownerLabel(owner){return owner==='mine'?tr('mineOwned'):tr('employerOwned');}
function toast(message){toastNode.textContent=message;toastNode.classList.add('show');clearTimeout(toastNode._timer);toastNode._timer=setTimeout(function(){toastNode.classList.remove('show');},2200);}
function openModal(html){modalReturnFocus=document.activeElement;modalBody.innerHTML=html;var heading=$('h2',modalBody);if(heading)heading.id='modalTitle';modal.hidden=false;setTimeout(function(){var f=$('input,select,textarea,button',modalBody);if(f)f.focus();},0);}
