function stats(){var clear=0,restricted=0,action=0,on=0;state.workers.forEach(function(w){var c=readiness(w).code;if(c==='clear')clear++;else if(c==='restricted')restricted++;else action++;if(w.checkedIn)on++;});return '<div class="grid stats"><div class="card stat"><strong>'+state.workers.length+'</strong><span>'+esc(tr('expected'))+'</span></div><div class="card stat"><strong>'+clear+'</strong><span>'+esc(tr('clear'))+'</span></div><div class="card stat"><strong>'+restricted+'</strong><span>'+esc(tr('restricted'))+'</span></div><div class="card stat"><strong>'+action+'</strong><span>'+esc(tr('action'))+'</span></div><div class="card stat"><strong>'+on+'</strong><span>'+esc(tr('onsite'))+'</span></div></div>';}
