 var cats='<div class="category-grid">'+categoryCard('changes','↻','Equipment, routes, conditions, procedures, and mine notices.','Equipos, rutas, condiciones, procedimientos y avisos de la mina.')+categoryCard('prevention','△','Hazard recognition, task controls, powered haulage, guarding, and lessons learned.','Reconocimiento de peligros, controles de tareas, acarreo, protección y lecciones aprendidas.')+categoryCard('response','⚑','Emergency communication, evacuation, first aid, reporting, and escalation.','Comunicación de emergencia, evacuación, primeros auxilios, reportes y escalamiento.')+'</div>';
 var programs='<div class="grid programs-grid"><div class="card"><div class="program-tag">§46.5</div><h3>'+esc(tr('newMiner'))+'</h3><p class="meta">'+esc(state.lang==='es'?'Controla 4 horas antes de trabajar, requisitos de 60 días, 24 horas totales, plazo de 90 días y observación.':'Tracks four hours before work, 60-day items, 24 total hours, the 90-day deadline, and observation.')+'</p></div><div class="card"><div class="program-tag">§46.6</div><h3>'+esc(tr('experienced'))+'</h3><p class="meta">'+esc(state.lang==='es'?'Controla verificación de experiencia, siete temas antes de trabajar y el requisito respiratorio de 60 días cuando aplique.':'Tracks experience verification, seven before-work subjects, and the 60-day respiratory item when applicable.')+'</p></div><div class="card"><div class="program-tag">§46.8</div><h3>'+esc(tr('ledger'))+'</h3><p class="meta">'+esc(state.lang==='es'?'Acumula sesiones cortas certificadas hacia ocho horas y muestra crédito por categoría.':'Accumulates certified short sessions toward eight hours and shows credit by category.')+'</p></div><div class="card"><div class="program-tag">§46.7</div><h3>'+esc(tr('taskProgram'))+'</h3><p class="meta">'+esc(state.lang==='es'?'Mantiene la capacitación de tareas separada de la autorización de acceso.':'Keeps task training separate from site-access authorization.')+'</p></div><div class="card"><div class="program-tag">§46.11</div><h3>'+esc(tr('siteProgram'))+'</h3><p class="meta">'+esc(state.lang==='es'?'La mina controla los peligros específicos del sitio y las confirmaciones de cambios.':'The mine controls site-specific hazards and changed-condition acknowledgments.')+'</p></div></div>';
