function renderPeople(){return hero(tr('people'),tr('warning'))+'<div class="actions"><input id="peopleSearch" class="input" style="flex:3" placeholder="'+esc(tr('search'))+'"><button class="btn" data-action="import">'+esc(tr('importCsv'))+'</button><button class="btn" data-action="export">'+esc(tr('exportCsv'))+'</button><input id="csvFile" type="file" accept=".csv,text/csv" hidden></div><div class="section-head"><h2>'+esc(tr('workers'))+'</h2></div><div id="peopleList" class="worker-list">'+state.workers.map(function(w){return workerRow(w,'<br><button class="btn small" data-worker-action="'+(state.role==='mine'?'gate':'progress')+'" data-worker="'+esc(w.id)+'">'+esc(state.role==='mine'?tr('openGate'):tr('viewProgress'))+'</button>');}).join('')+'</div>';}
