function preApprovalChecks(w){var p=programAssessment(w);return {identity:w.identity,program:!p.blocked,task:w.taskCurrent,orientation:w.orientationCurrent,notice:Number(w.noticeVersion)===Number(state.siteNoticeVersion),hold:!w.hold,restriction:p.restriction};}
function renderGate(){var w=worker(state.activeWorker)||state.workers[0],r=readiness(w),c=preApprovalChecks(w),canApprove=c.identity&&c.program&&c.task&&c.orientation&&c.notice&&c.hold;var result=statusLabel(r.code);var action='';if(canApprove&&(!w.mineApproval||w.approvalKey!==approvalKeyFor(w)))action+='<button class="btn primary" data-action="approve" data-worker="'+esc(w.id)+'">'+esc(tr('approve'))+'</button>';if(r.code==='clear'||r.code==='restricted')action+='<button class="btn primary" data-action="'+(w.checkedIn?'checkout':'checkin')+'" data-worker="'+esc(w.id)+'">'+esc(w.checkedIn?tr('checkOut'):tr('checkIn'))+'</button>';action+='<button class="btn '+(w.hold?'':'danger')+'" data-action="'+(w.hold?'remove-hold':'hold')+'" data-worker="'+esc(w.id)+'">'+esc(w.hold?tr('removeHold'):tr('placeHold'))+'</button>';return hero(tr('gate'),tr('approvalScope'))+'<div class="grid two"><section class="card"><label class="field">'+esc(tr('selectWorker'))+'<select id="gateWorker" class="select">'+state.workers.map(function(x){return '<option value="'+esc(x.id)+'"'+(x.id===w.id?' selected':'')+'>'+esc(x.name)+' · '+esc(x.id)+'</option>';}).join('')+'</select></label><div class="gate-main" style="margin-top:18px">'+avatar(w)+'<h2>'+esc(w.name)+'</h2><div class="meta">'+esc(w.employer)+' · '+esc(w.workOrder)+'</div><div class="gate-result '+r.code+'" role="status">'+esc(result)+'</div><p class="meta">'+esc(r.reason?tr(r.reason):tr('approvalScope'))+'</p>'+(r.restriction?'<div class="warning">'+esc(tr('restrictedExplanation'))+'<br><strong>'+esc(w.observer||'')+'</strong></div>':'')+'<div class="check-grid" style="margin-top:16px">'+checkRow(tr('identity'),c.identity)+checkRow(tr('programReady'),c.program,!!c.restriction)+checkRow(tr('task'),c.task)+checkRow(tr('orientation'),c.orientation)+checkRow(tr('notice'),c.notice)+checkRow(tr('approval'),w.mineApproval&&w.approvalKey===approvalKeyFor(w))+checkRow(tr('hold'),c.hold)+'</div><div class="actions" style="margin-top:15px">'+action+'</div></div></section><aside><div class="section-head"><h2>'+esc(tr('programSummary'))+'</h2></div>'+programCard(w)+'<div class="section-head"><h2>'+esc(tr('people'))+'</h2></div><div class="worker-list">'+state.workers.map(function(x){return workerRow(x,'<br><button class="btn small" data-worker-action="gate" data-worker="'+esc(x.id)+'">'+esc(tr('openGate'))+'</button>');}).join('')+'</div></aside></div>';}
function annualLedger(w){var total=annualMinutes(w.id),pending=annualPending(w.id),pct=Math.min(100,Math.round(total/480*100));var cats=['changes','prevention','response'];return '<div class="card"><div class="program-tag">§46.8</div><h2 style="margin:5px 0">'+esc(tr('ledger'))+'</h2><div class="progress-line"><span>'+esc(tr('credited'))+'</span><strong>'+hoursText(total)+' / 8 '+esc(tr('hours'))+'</strong></div><div class="progress"><i style="width:'+pct+'%"></i></div><div class="milestones"><div class="milestone"><span>'+esc(tr('pendingCredit'))+'</span><strong>'+hoursText(pending)+'</strong></div><div class="milestone"><span>'+esc(tr('annualCurrent'))+'</span><strong>'+esc(fmtDate(w.annualCurrentThrough))+'</strong></div></div><div class="section-head"><h2>'+esc(tr('planCategories'))+'</h2></div>'+cats.map(function(cat){var m=categoryMinutes(w.id,cat);return '<div class="progress-line"><span>'+esc(tr(cat))+'</span><strong>'+hoursText(m)+'</strong></div><div class="progress"><i style="width:'+Math.min(100,Math.round(m/480*100))+'%"></i></div>';}).join('')+'<div class="warning" style="margin-top:12px">'+esc(tr('annualNotBlocked'))+'</div></div>';}
function recordsFor(id){return state.records.filter(function(r){return r.workerId===id;}).sort(function(a,b){return String(b.date).localeCompare(String(a.date));});}
function recordMinutes(r){var actual=Number(r.minutes||0),credit=r.annualCredit?Number(r.annualCreditedMinutes!=null?r.annualCreditedMinutes:actual):0;return {actual:actual,credit:credit};}
function recordsHtml(w){var list=recordsFor(w.id);var mobile='<div class="record-mobile">'+list.map(function(r){var mins=recordMinutes(r);return '<div class="record"><strong>'+esc(local(r,'title'))+'</strong><small>'+esc(programTitle(r.program))+' · '+esc(tr(r.category))+' · '+mins.actual+' '+esc(tr('mins'))+(r.annualCredit?' · '+mins.credit+' '+esc(tr('credited')):'')+'<br>'+esc(fmtDate(r.date))+' · '+esc(r.certifier)+'</small></div>';}).join('')+'</div>';var table='<table class="ledger-table desktop-only"><thead><tr><th>'+esc(tr('title'))+'</th><th>'+esc(tr('program'))+'</th><th>'+esc(tr('category'))+'</th><th>'+esc(tr('certifier'))+'</th><th>'+esc(tr('actualMinutes'))+'</th></tr></thead><tbody>'+list.map(function(r){var mins=recordMinutes(r);return '<tr><td>'+esc(local(r,'title'))+'<br><span class="meta">'+esc(fmtDate(r.date))+'</span></td><td>'+esc(programTitle(r.program))+'</td><td>'+esc(tr(r.category))+'</td><td>'+esc(r.certifier)+'</td><td>'+mins.actual+(r.annualCredit?'<br><span class="meta">'+mins.credit+' '+esc(tr('credited'))+'</span>':'')+'</td></tr>';}).join('')+'</tbody></table>';return list.length?mobile+table:'<div class="card empty">'+esc(tr('noRecords'))+'</div>';}
function renderWorkerProgress(w){return hero(tr('progress'),tr('warning'))+(w.program==='46.8'?annualLedger(w):programCard(w))+'<div class="section-head"><h2>'+esc(tr('records'))+'</h2></div>'+recordsHtml(w);}
function renderWorkerHome(){var w=worker(state.activeWorker),r=readiness(w),next=state.assignments.filter(function(a){return a.workerId===w.id&&a.status!=='certified';});return hero(tr('home'),tr('warning'))+roleGuide()+'<div class="grid two"><section><div class="card gate-main">'+avatar(w)+'<h2>'+esc(w.name)+'</h2><div class="meta">'+esc(w.employer)+' · '+esc(w.role)+'</div><div class="gate-result '+r.code+'" role="status">'+esc(statusLabel(r.code))+'</div><p class="meta">'+esc(r.reason?tr(r.reason):tr('approvalScope'))+'</p><div class="actions"><button class="btn primary" data-page="pass">'+esc(tr('viewPass'))+'</button><button class="btn" data-page="progress">'+esc(tr('viewProgress'))+'</button></div></div><div class="section-head"><h2>'+esc(tr('training'))+'</h2></div><div class="assignment-list">'+(next.map(assignmentCard).join('')||'<div class="card empty">'+esc(tr('noItems'))+'</div>')+'</div></section><aside>'+programCard(w)+'</aside></div>';}
function qrPayload(w){return 'https://mineready.zerodaycyber.io/?workspace=mine&worker='+encodeURIComponent(w.id)+'&lang=en';}
function qrFor(w){var known=['ZMR-1042','ZMR-1049','ZMR-1056','ZMR-1088'];if(typeof window.qrcode==='function'){try{var code=window.qrcode(0,'Q');code.addData(qrPayload(w));code.make();return '<div class="qr-generated" aria-label="QR pass for '+esc(w.name)+'">'+code.createSvgTag(6,4)+'</div>';}catch(e){}}
 if(known.indexOf(w.id)>=0)return '<img class="qr-image" src="./assets/qr/'+encodeURIComponent(w.id)+'.png" alt="QR pass for '+esc(w.name)+'">';
 return '<div class="qr-unavailable" role="status">'+esc(state.lang==='es'?'El código QR no está disponible. Use el ID del trabajador en la entrada.':'QR code unavailable. Use the worker ID at the gate.')+'</div>';}
function renderPass(){var w=worker(state.activeWorker),r=readiness(w);return hero(tr('pass'),tr('showAtGate'))+'<div class="card qr-card">'+avatar(w)+'<h2>'+esc(w.name)+'</h2><div class="meta">'+esc(w.employer)+'<br>'+esc(tr('workOrder'))+': '+esc(w.workOrder)+'</div><div class="gate-result '+r.code+'">'+esc(statusLabel(r.code))+'</div>'+qrFor(w)+'<strong>'+esc(w.id)+'</strong><p class="meta">'+esc(tr('approvalScope'))+'</p></div>';}
function renderProfile(){var w=worker(state.activeWorker);return hero(tr('profile'),tr('warning'))+'<div class="card" style="max-width:680px">'+workerRow(w,'')+'<div class="milestones" style="margin-top:14px"><div class="milestone"><span>'+esc(tr('workerId'))+'</span><strong>'+esc(w.id)+'</strong></div><div class="milestone"><span>'+esc(tr('employerName'))+'</span><strong>'+esc(w.employer)+'</strong></div><div class="milestone"><span>'+esc(tr('program'))+'</span><strong>'+esc(programTitle(w.program))+'</strong></div><div class="milestone"><span>'+esc(tr('language'))+'</span><strong>'+esc(w.preferredLang==='es'?tr('spanish'):tr('english'))+'</strong></div></div><div class="actions" style="margin-top:14px"><button class="btn danger" data-action="reset">'+esc(tr('resetDemo'))+'</button></div></div>';}
function renderCourse(){var a=assignment(state.courseId),w=a&&worker(a.workerId);if(!a||!w){state.page='training';return renderTraining();}var step=Number(state.courseStep||0),body='';if(step<3){var key=step===0?'lessonOverview':step===1?'lessonControls':'lessonScenario';body='<div class="course-step">'+esc(tr('courseStep'))+' '+(step+1)+' / 3</div><h2>'+esc(local(a,'title'))+'</h2><p>'+esc(tr(key))+'</p><div class="card soft"><h3>'+esc(tr(a.category))+'</h3><p>'+esc(local(a,'subject'))+'</p></div><ul><li>'+esc(tr('warning'))+'</li><li>'+esc(tr('annualCreditNote'))+'</li><li>'+esc(tr('approvalScope'))+'</li></ul><div class="actions"><button class="btn" data-course="back">'+esc(tr('back'))+'</button><button class="btn primary" data-course="next">'+esc(tr('next'))+'</button></div>';}else{body='<div class="course-step">'+esc(tr('knowledgeCheck'))+'</div><h2>'+esc(local(a,'title'))+'</h2>'+[['q1','a1'],['q2','a2'],['q3','a3']].map(function(q,i){return '<div><p><strong>'+(i+1)+'. '+esc(tr(q[0]))+'</strong></p><label class="quiz-option"><input type="radio" name="q'+i+'" value="ok">'+esc(tr(q[1]))+'</label><label class="quiz-option"><input type="radio" name="q'+i+'" value="bad">'+esc(tr('wrong'))+'</label></div>';}).join('')+'<label class="field">'+esc(tr('signature'))+'<input id="courseSignature" class="input" value="'+esc(w.name)+'"></label><label class="quiz-option"><input id="courseAck" type="checkbox">'+esc(tr('ack'))+'</label><div class="actions"><button class="btn" data-course="back">'+esc(tr('back'))+'</button><button class="btn primary" data-course="submit">'+esc(tr('submit'))+'</button></div>';}
 return hero(tr('training'),programTitle(a.program))+'<div class="card course-shell">'+body+'</div>';
}
function render(){
 try{
  document.documentElement.lang=state.lang;var body='';if(state.page==='course')body=renderCourse();else if(state.role==='mine')body=state.page==='gate'?renderGate():state.page==='training'?renderTraining():state.page==='programs'?renderPrograms():state.page==='people'?renderPeople():renderDashboard();else if(state.role==='employer')body=state.page==='training'?renderTraining():state.page==='reviews'?renderReviews():state.page==='programs'?renderPrograms():state.page==='people'?renderPeople():renderDashboard();else{var w=worker(state.activeWorker)||state.workers[0];state.activeWorker=w.id;body=state.page==='training'?renderTraining():state.page==='progress'?renderWorkerProgress(w):state.page==='pass'?renderPass():state.page==='profile'?renderProfile():renderWorkerHome();}
  app.innerHTML='<div class="app">'+header()+'<main class="shell">'+navigation()+body+'</main></div>';save();syncUrl();
 }catch(err){app.innerHTML='<main class="boot"><div><img src="./assets/icon.svg" alt="Zeroday"><h1>MineReady could not start</h1><p>'+esc(err&&err.message?err.message:'Application error')+'</p><a href="?reset=1">Reset demo and reload</a></div></main>';}
}
function syncUrl(){try{var p=new URLSearchParams();p.set('workspace',state.role);p.set('lang',state.lang);if(state.activeWorker)p.set('worker',state.activeWorker);history.replaceState(null,'',location.pathname+'?'+p.toString());}catch(e){}}
function applyUrl(){try{var p=new URLSearchParams(location.search),r=p.get('workspace'),l=p.get('lang'),w=p.get('worker');if(['mine','employer','worker'].indexOf(r)>=0)state.role=r;if(['en','es'].indexOf(l)>=0)state.lang=l;if(w&&worker(w))state.activeWorker=w;state.page=state.role==='worker'?'home':'dashboard';}catch(e){}}
function assignmentModal(){var workerChecks=state.workers.map(function(w){return '<label class="worker-check"><input type="checkbox" name="assignWorker" value="'+esc(w.id)+'"><span><strong>'+esc(w.name)+'</strong><br><small class="meta">'+esc(programTitle(w.program))+' · '+esc(w.employer)+'</small></span></label>';}).join('');openModal('<h2>'+esc(tr('newAssignment'))+'</h2><div class="form-grid"><div class="field">'+esc(tr('workers'))+'<div class="worker-checks">'+workerChecks+'</div></div><div class="form-grid two-col"><label class="field">'+esc(tr('title'))+' · '+esc(tr('english'))+'<input id="asTitle" class="input" maxlength="120" required></label><label class="field">'+esc(tr('title'))+' · '+esc(tr('spanish'))+'<input id="asTitleEs" class="input" maxlength="120"></label><label class="field">'+esc(tr('program'))+'<select id="asProgram" class="select"><option value="46.8">'+esc(tr('annualProgram'))+'</option><option value="46.5">'+esc(tr('newMiner'))+'</option><option value="46.6">'+esc(tr('experienced'))+'</option><option value="46.7">'+esc(tr('taskProgram'))+'</option><option value="46.11">'+esc(tr('siteProgram'))+'</option></select></label><label class="field">'+esc(tr('category'))+'<select id="asCategory" class="select"><option value="changes">'+esc(tr('changes'))+'</option><option value="prevention">'+esc(tr('prevention'))+'</option><option value="response">'+esc(tr('response'))+'</option></select></label><label class="field">'+esc(tr('minutes'))+'<input id="asMinutes" class="input" type="number" min="5" max="480" value="20"></label><label class="field">'+esc(tr('due'))+'<input id="asDue" class="input" type="date" value="'+addDays(7)+'" min="'+isoDate(new Date())+'"></label><label class="field">'+esc(tr('language'))+'<select id="asLang" class="select"><option value="preferred">'+esc(tr('both'))+'</option><option value="en">'+esc(tr('english'))+'</option><option value="es">'+esc(tr('spanish'))+'</option></select></label><label class="field">'+esc(tr('reviewOwner'))+'<select id="asOwner" class="select"><option value="employer">'+esc(tr('employerReview'))+'</option><option value="mine">'+esc(tr('mineReview'))+'</option></select></label><label class="field">'+esc(tr('milestone'))+'<select id="asMilestone" class="select"><option value="annual">'+esc(tr('annualLedger'))+'</option><option value="46.5-prework">'+esc(tr('prework46_5'))+'</option><option value="46.5-firstaid">'+esc(tr('firstaid46_5'))+'</option><option value="46.5-resp">'+esc(tr('resp46_5'))+'</option><option value="46.5-balance">'+esc(tr('balance46_5'))+'</option><option value="46.6-prework">'+esc(tr('prework46_6'))+'</option><option value="46.6-resp">'+esc(tr('resp46_6'))+'</option><option value="task">'+esc(tr('taskMilestone'))+'</option><option value="site">'+esc(tr('siteAwareness'))+'</option><option value="general">'+esc(tr('general'))+'</option></select></label></div><div class="form-grid two-col"><label class="field">'+esc(tr('subject'))+' · '+esc(tr('english'))+'<textarea id="asSubject" class="textarea" maxlength="240"></textarea></label><label class="field">'+esc(tr('subject'))+' · '+esc(tr('spanish'))+'<textarea id="asSubjectEs" class="textarea" maxlength="240"></textarea></label></div><p class="translation-help">'+esc(state.lang==='es'?'El contenido en español es opcional para capacitación personalizada; si se deja vacío, se usa el contenido en inglés.':'Spanish content is optional for custom training; English is used as the fallback when it is blank.')+'</p><label class="quiz-option"><input id="asAnnualCredit" type="checkbox" checked><span><strong>'+esc(tr('annualCredit'))+'</strong><br><small class="meta">'+esc(tr('annualCreditNote'))+'</small></span></label><div class="actions"><button class="btn" data-action="modal-close">'+esc(tr('cancel'))+'</button><button class="btn primary" data-action="assign-save">'+esc(tr('saveAssignment'))+'</button></div></div>');updateAssignmentDefaults();}
function updateAssignmentDefaults(){var p=$('#asProgram');if(!p)return;var owner=$('#asOwner'),milestone=$('#asMilestone'),credit=$('#asAnnualCredit');if(p.value==='46.11'){owner.value='mine';milestone.value='site';credit.checked=false;}else if(p.value==='46.7'){owner.value='employer';milestone.value='task';credit.checked=false;}else if(p.value==='46.5'){owner.value='employer';milestone.value='46.5-balance';credit.checked=false;}else if(p.value==='46.6'){owner.value='employer';milestone.value='46.6-prework';credit.checked=false;}else{owner.value='employer';milestone.value='annual';credit.checked=true;}}
function saveAssignment(){var ids=$$('input[name="assignWorker"]:checked',modalBody).map(function(x){return x.value;}),title=clean($('#asTitle').value,120),titleEs=clean($('#asTitleEs').value,120)||title,subject=clean($('#asSubject').value,240),subjectEs=clean($('#asSubjectEs').value,240)||subject,program=$('#asProgram').value,minutes=Number($('#asMinutes').value),due=$('#asDue').value;if(!ids.length){toast(tr('noWorker'));return;}if(!title||!subject||!due||minutes<5||minutes>480){toast(tr('requiredFields'));return;}ids.forEach(function(id){var w=worker(id),lang=$('#asLang').value;state.assignments.push({id:'A'+Date.now()+'-'+Math.random().toString(36).slice(2,6),workerId:id,title:title,titleEs:titleEs,program:program,category:$('#asCategory').value,subject:subject,subjectEs:subjectEs,minutes:minutes,due:due,language:lang==='preferred'?(w.preferredLang||'en'):lang,owner:$('#asOwner').value,milestone:$('#asMilestone').value,annualCreditRequested:$('#asAnnualCredit').checked,status:'assigned',step:0,quiz:''});});closeModal();toast(tr('assignedMessage'));render();}
function reviewModal(id){var a=assignment(id),w=a&&worker(a.workerId);if(!a||!w)return;openModal('<h2>'+esc(tr('review'))+'</h2><div class="warning">'+esc(tr('certificationWarning'))+'</div><div class="card soft" style="margin:12px 0"><strong>'+esc(local(a,'title'))+'</strong><div class="meta">'+esc(w.name)+' · '+esc(programTitle(a.program))+' · '+esc(tr(a.category))+'</div></div><div class="form-grid two-col"><label class="field">'+esc(tr('actualMinutes'))+'<input id="rvMinutes" class="input" type="number" min="1" max="'+Number(a.minutes)+'" value="'+Number(a.completedMinutes||a.minutes)+'"></label><label class="field">'+esc(tr('creditedMinutes'))+'<input id="rvCreditMinutes" class="input" type="number" min="0" max="'+Number(a.minutes)+'" value="'+(a.annualCreditRequested?Number(a.completedMinutes||a.minutes):0)+'" '+(a.annualCreditRequested?'':'disabled')+'></label><label class="field">'+esc(tr('reviewer'))+'<input id="rvReviewer" class="input" maxlength="100" value="'+esc(state.role==='mine'?'Morgan Lee':'Taylor Greene')+'"></label><label class="field">'+esc(tr('competentPerson'))+'<input id="rvCompetent" class="input" maxlength="100" value="R. Ortega"></label></div><label class="field">'+esc(tr('rejectReason'))+'<textarea id="rvNote" class="textarea" maxlength="240"></textarea></label><div class="actions"><button class="btn" data-action="modal-close">'+esc(tr('cancel'))+'</button><button class="btn danger" data-action="review-reject" data-id="'+esc(a.id)+'">'+esc(tr('reject'))+'</button><button class="btn primary" data-action="review-certify" data-id="'+esc(a.id)+'">'+esc(tr('certify'))+'</button></div>');}
function certifyAssignment(id){var a=assignment(id),w=a&&worker(a.workerId);if(!a||!w||a.status!=='awaiting_review')return;if(a.owner!==state.role){toast(a.owner==='mine'?tr('mineOwned'):tr('employerOwned'));return;}var actual=Number($('#rvMinutes').value),credit=Number($('#rvCreditMinutes').value||0),reviewer=clean($('#rvReviewer').value,100),competent=clean($('#rvCompetent').value,100);if(!actual||actual<1||actual>Number(a.minutes)||!reviewer||!competent){toast(tr('requiredFields'));return;}if(credit<0||credit>actual||(!a.annualCreditRequested&&credit>0)){toast(tr('annualCreditNote'));return;}a.status='certified';a.actualMinutes=actual;a.creditedMinutes=credit;a.certifiedAt=new Date().toISOString();a.certifiedBy=reviewer;a.competentPerson=competent;var record={id:'R'+Date.now(),workerId:w.id,title:a.title,titleEs:a.titleEs,program:a.program,category:a.category,subject:a.subject,subjectEs:a.subjectEs||a.subject,minutes:actual,annualCredit:credit>0,date:isoDate(new Date()),competentPerson:competent,certifier:reviewer,owner:a.owner,primaryProgram:a.program,annualCreditedMinutes:credit,planVersion:state.plan.version,location:'Silver Ridge Quarry / mobile or field session',evaluation:'Knowledge check, acknowledgment, and authorized review'};state.records.push(record);
 if(a.program==='46.5'){w.total46_5Minutes=Number(w.total46_5Minutes||0)+actual;if(a.milestone==='46.5-prework'){w.preWorkMinutes=Number(w.preWorkMinutes||0)+actual;w.preWorkSubjectsComplete=true;}if(a.milestone==='46.5-firstaid')w.firstAidComplete=true;if(a.milestone==='46.5-resp')w.respiratoryComplete=true;}
 if(a.program==='46.6'){if(a.milestone==='46.6-prework')w.preWorkSubjects=Math.min(7,Number(w.preWorkSubjects||0)+1);if(a.milestone==='46.6-resp')w.respiratoryComplete=true;}
 if(a.program==='46.7')w.taskCurrent=true;if(a.program==='46.11'){w.orientationCurrent=true;w.noticeVersion=state.siteNoticeVersion;}
 w.mineApproval=false;w.approvalKey='';w.checkedIn=false;closeModal();toast(tr('certifiedMessage'));render();}
function rejectAssignment(id){var a=assignment(id);if(!a||a.owner!==state.role)return;a.status='rejected';a.reviewNote=clean($('#rvNote').value,240)||tr('rejectedMessage');a.step=0;a.quiz='';closeModal();toast(tr('rejectedMessage'));render();}
function startCourse(id){var a=assignment(id);if(!a)return;state.courseId=id;state.courseStep=Number(a.step||0);a.status='in_progress';state.role='worker';state.activeWorker=a.workerId;state.lang=a.language==='es'?'es':a.language==='en'?'en':state.lang;state.page='course';render();}
function courseAction(action){var a=assignment(state.courseId);if(!a)return;if(action==='next'){state.courseStep=Math.min(3,state.courseStep+1);a.step=state.courseStep;render();}else if(action==='back'){if(state.courseStep>0){state.courseStep--;a.step=state.courseStep;render();}else{state.page='training';render();}}else if(action==='submit'){var ok=true;for(var i=0;i<3;i++){var c=$('input[name="q'+i+'"]:checked');if(!c||c.value!=='ok')ok=false;}var sig=clean($('#courseSignature').value,100),ack=$('#courseAck').checked;if(!ok||!sig||!ack){toast(tr('tryAgain'));return;}a.status='awaiting_review';a.quiz='passed';a.completedMinutes=Number(a.minutes);a.completedAt=new Date().toISOString();a.signature=sig;a.step=3;state.page='home';toast(tr('reviewRequired'));render();}}
function approveWorker(id){if(state.role!=='mine')return;var w=worker(id),c=preApprovalChecks(w);if(!(c.identity&&c.program&&c.task&&c.orientation&&c.notice&&c.hold)){toast(tr('notReadyMessage'));return;}w.mineApproval=true;w.approvalKey=approvalKeyFor(w);w.approvedAt=new Date().toISOString();w.approvedBy='Morgan Lee';toast(tr('approvedMessage'));render();}
function checkWorker(id,inOut){if(state.role!=='mine')return;var w=worker(id),r=readiness(w);if(inOut&&!(r.code==='clear'||r.code==='restricted')){toast(tr('notReadyMessage'));return;}w.checkedIn=inOut;w.checkedAt=inOut?new Date().toISOString():'';toast(inOut?tr('checkedInMessage'):tr('checkOut'));render();}
function exportCsv(){var rows=[['worker_id','name','employer','role','crew','work_order','program','status','checked_in']];state.workers.forEach(function(w){rows.push([w.id,w.name,w.employer,w.role,w.crew,w.workOrder,w.program,readiness(w).code,w.checkedIn?'yes':'no']);});var csv=rows.map(function(row){return row.map(function(v){var s=String(v==null?'':v);if(/^\s*[=+\-@]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}).join(',');}).join('\r\n');var blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='mineready-workforce-'+isoDate(new Date())+'.csv';document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(url);},0);}
function parseCsv(text){var rows=[],row=[],field='',quoted=false;for(var i=0;i<text.length;i++){var c=text.charAt(i),n=text.charAt(i+1);if(quoted){if(c==='"'&&n==='"'){field+='"';i++;}else if(c==='"')quoted=false;else field+=c;}else if(c==='"')quoted=true;else if(c===','){row.push(field);field='';}else if(c==='\n'){row.push(field.replace(/\r$/,''));rows.push(row);row=[];field='';}else field+=c;}if(field||row.length){row.push(field.replace(/\r$/,''));rows.push(row);}return rows.filter(function(r){return r.some(function(x){return x.trim();});});}
function importCsv(file){if(!file)return;if(file.size>1048576){toast(tr('fileTooLarge'));return;}var reader=new FileReader();reader.onload=function(){try{var rows=parseCsv(String(reader.result).replace(/^\ufeff/,''));if(rows.length<2){toast(tr('invalidCsv'));return;}if(rows.length-1>500){toast(tr('maxRows'));return;}var headers=rows.shift().map(function(h){return clean(h,60).toLowerCase().replace(/\s+/g,'_');}),aliases={id:['worker_id','id','id_trabajador','identificador'],name:['name','nombre'],employer:['employer','empleador','empresa'],role:['role','puesto','cargo'],crew:['crew','cuadrilla','equipo'],workOrder:['work_order','orden_de_trabajo','orden_trabajo']},idx={};Object.keys(aliases).forEach(function(k){idx[k]=-1;for(var j=0;j<headers.length;j++)if(aliases[k].indexOf(headers[j])>=0){idx[k]=j;break;}});if(idx.id<0||idx.name<0){toast(tr('invalidCsv'));return;}var count=0;rows.forEach(function(r){var val=function(k,max){return idx[k]>=0?clean(r[idx[k]],max):'';},id=val('id',40),name=val('name',100);if(!/^[A-Za-z0-9_-]{2,40}$/.test(id)||!name||worker(id))return;state.workers.push({id:id,name:name,preferredLang:'en',employer:val('employer',120)||'Imported Contractor',role:val('role',100)||'Worker',crew:val('crew',80)||'Unassigned',workOrder:val('workOrder',80)||'Pending',program:'46.8',identity:false,taskCurrent:false,orientationCurrent:false,noticeVersion:0,mineApproval:false,approvalKey:'',hold:false,checkedIn:false,annualCurrentThrough:addDays(-1),annualCycleDue:addDays(365)});count++;});toast(count+' '+tr('imported'));render();}catch(e){toast(tr('invalidCsv'));}};reader.readAsText(file);}
function resetDemo(){if(confirm(tr('resetConfirm'))){localStorage.removeItem(STORE);state=makeInitial();render();}}
document.addEventListener('click',function(event){var b=event.target.closest('button,a');if(!b)return;if(b.dataset.lang){state.lang=b.dataset.lang;render();return;}if(b.dataset.page){state.page=b.dataset.page;render();return;}if(b.dataset.action==='modal-close'){closeModal();return;}if(b.dataset.action==='assign-open'){assignmentModal();return;}if(b.dataset.action==='assign-save'){saveAssignment();return;}if(b.dataset.review){reviewModal(b.dataset.review);return;}if(b.dataset.action==='review-certify'){certifyAssignment(b.dataset.id);return;}if(b.dataset.action==='review-reject'){rejectAssignment(b.dataset.id);return;}if(b.dataset.startCourse){startCourse(b.dataset.startCourse);return;}if(b.dataset.course){courseAction(b.dataset.course);return;}if(b.dataset.workerAction){state.activeWorker=b.dataset.worker;state.page=b.dataset.workerAction==='gate'?'gate':'programs';render();return;}if(b.dataset.action==='approve'){approveWorker(b.dataset.worker);return;}if(b.dataset.action==='checkin'){checkWorker(b.dataset.worker,true);return;}if(b.dataset.action==='checkout'){checkWorker(b.dataset.worker,false);return;}if(b.dataset.action==='hold'&&state.role==='mine'){var wh=worker(b.dataset.worker);wh.hold=true;wh.mineApproval=false;wh.checkedIn=false;render();return;}if(b.dataset.action==='remove-hold'&&state.role==='mine'){worker(b.dataset.worker).hold=false;render();return;}if(b.dataset.action==='export'){exportCsv();return;}if(b.dataset.action==='import'){$('#csvFile').click();return;}if(b.dataset.action==='reset'){resetDemo();return;}});
document.addEventListener('change',function(event){if(event.target.id==='workspace'){state.role=event.target.value;state.page=state.role==='worker'?'home':'dashboard';if(state.role==='worker'&&!worker(state.activeWorker))state.activeWorker=state.workers[0].id;render();}if(event.target.id==='gateWorker'){state.activeWorker=event.target.value;render();}if(event.target.id==='asProgram')updateAssignmentDefaults();if(event.target.id==='csvFile'){var f=event.target.files&&event.target.files[0];event.target.value='';importCsv(f);}});
