modal.addEventListener('click',function(event){if(event.target===modal)closeModal();});window.addEventListener('keydown',function(event){if(event.key==='Escape'){closeModal();return;}if(event.key==='Tab'&&!modal.hidden){var focusable=$$('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href]',modal),first=focusable[0],last=focusable[focusable.length-1];if(!first)return;if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
